argv:
$ErrorActionPreference='Stop'
$src='E:\WebAIBridge\app\server.js'
Write-Output '=== PAUSE/RESUME ROUTE SOURCE ==='
$patterns=@("url.pathname === '/api/settings'","url.pathname === '/api/ai-profiles'","url.pathname === '/api/supervisor-watchdog/queue'","settings.paused =","settings.paused=","paused:","pause-assignments","/api/supervisor-watchdog/agent")
foreach($p in $patterns) {
 $m=@(Select-String -LiteralPath $src -SimpleMatch -Pattern $p|Select-Object -First 18)
 Write-Output ('PATTERN '+$p+' COUNT_SHOWN='+$m.Count)
 foreach($hit in $m){Write-Output ('LINE '+$hit.LineNumber+' '+$hit.Line.Trim().Substring(0,[Math]::Min(175,$hit.Line.Trim().Length)))}
}
Write-Output '=== END ==='
